import ast, json, sys
from pathlib import Path
sys.path.insert(0, '/Users/alexseverin/basilisp-tools/scripts')
from python_typing_corpus import fixtures
cases = {
    'Overloads / Invalid / Inconsistent decorators / `@staticmethod`': [
        'instance.method1(1)', 'instance.method2("a")', 'instance.method3(1)',
    ],
    'Overloads / Invalid / Inconsistent decorators / `@classmethod`': [
        'CheckClassMethod.try_from3(CheckClassMethod, 1)',
        'CheckClassMethod.try_from1(instance, "a")', 'CheckClassMethod.try_from1(1)',
    ],
}
result = {'python': sys.version, 'fixtures': []}
for fixture in fixtures('ty', Path('/tmp/blt-python-types-20261006/astral-sh-ruff')):
    if fixture['name'] not in cases:
        continue
    source = fixture['files']['mdtest_snippet.py']
    tree = ast.parse(source)
    tree.body = [n for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom, ast.ClassDef, ast.FunctionDef))]
    namespace = {}
    exec(compile(tree, '<reviewed-upstream-declarations>', 'exec'), namespace)
    namespace['instance'] = (namespace['CheckStaticMethod']() if 'CheckStaticMethod' in namespace
                             else namespace['CheckClassMethod'](1))
    rows = []
    for expression in cases[fixture['name']]:
        try:
            value = eval(expression, namespace)
            rows.append({'expression': expression, 'returned_type': type(value).__name__,
                         'value': value if type(value) in (str, int, bool, type(None)) else '<instance>'})
        except Exception as error:
            rows.append({'expression': expression, 'error_type': type(error).__name__, 'message': str(error)})
    result['fixtures'].append({'name': fixture['name'], 'source_sha256': fixture['source_sha256'], 'cases': rows})
print(json.dumps(result, indent=2))

