import inspect,json,sys
from collections import namedtuple
results=[]
for name,fields,defaults,mutate in [('NamedTuple2','field1,    field2',([],),True),('NamedTuple6','field1 field2 field3',[1,2],False)]:
 cls=namedtuple(name,fields,**({} if mutate else {'defaults':defaults}))
 if mutate:cls.__new__.__defaults__=defaults
 row={'name':name,'signature':str(inspect.signature(cls)),'valid_one_argument':repr(cls(1))}
 try:row['zero_arguments_result']=repr(cls())
 except Exception as error:row['zero_arguments_exception']=type(error).__name__;row['message']=str(error)
 results.append(row)
print(json.dumps({'python':sys.version,'cases':results},indent=2))

