from pathlib import Path
import json, sys, hashlib
source='''from typing import Callable, ParamSpec
P = ParamSpec("P")
def f(f: Callable[P, int], *args: P.args, **kwargs: P.kwargs) -> int:
    return f(*args, **kwargs) + f(*args, **kwargs)
x: Callable[..., int] = lambda: 1
'''
namespace={};exec(source,namespace)
records=[]
for expression in ('f(x)', 'f(x, 1)'):
    try:
        value=eval(expression,namespace)
    except TypeError as error:
        records.append({'expression':expression,'result':'TypeError','message':str(error)})
    else: records.append({'expression':expression,'result':value})
assert records[0]['result']==2 and records[1]['result']=='TypeError'
path=Path('/tmp/blt-python-mismatches-20261007')/f'pyrefly-ellipsis-native{sys.version_info.major}{sys.version_info.minor}.json'
path.write_text(json.dumps({'python':sys.version,'source':source,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'results':records},indent=2)+'\n')
print(path)

