import json,sys,typing
from enum import Enum
class EmptyEnum(Enum): ...
class C:
 @staticmethod
 def static_method(self,__x:int): ...
rows=[]
for expression,call in [('EmptyEnum(foo=1)',lambda:EmptyEnum(foo=1)),('C.static_method("x",__x=42)',lambda:C.static_method('x',__x=42)),('C.static_method("x",_C__x=42)',lambda:C.static_method('x',_C__x=42))]:
 try:
  value=call();result={'outcome':'returned','value':repr(value)}
 except Exception as exc:result={'outcome':'raised','exception':type(exc).__name__,'message':str(exc)}
 rows.append({'expression':expression,**result})
value=typing.Optional[None]
rows.append({'expression':'Optional[None]','outcome':'returned','value':repr(value),'is_None':value is None,'is_NoneType':value is type(None),'runtime_type':type(value).__name__})
print(json.dumps({'python':sys.version,'staticmethod_parameter_names':C.static_method.__code__.co_varnames,'cases':rows},indent=2))

